const passwordResetForm=document.querySelector("#passwordResetForm");const resetPasswordBtn=document.querySelector("#resetPasswordBtn");const passwordFeedback=document.querySelector("#passwordFeedback");passwordResetForm.onsubmit=event=>event.preventDefault();resetPasswordBtn.addEventListener("click",async()=>{try{const formData=new FormData(passwordResetForm);const res=await axios.post("/user/reset_password",formData);showToast(res.data);if(res.data.redirect){window.location=res.data.redirect}}catch(error){showToast({error:"Cannot Contact Server!"})}});const checkPassword=()=>{const password=document.querySelector("#InputPassword");password.addEventListener("input",async()=>{try{const res=await axios.post("/user/reset_password/checkPassword",{password:password.value});if(res.data.error){passwordFeedback.classList.remove("text-success");passwordFeedback.classList.add("text-danger");passwordFeedback.textContent=res.data.error}if(res.data.success){passwordFeedback.classList.remove("text-danger");passwordFeedback.classList.add("text-success");passwordFeedback.textContent=res.data.success}}catch(error){showToast({error:"Cannot Contact Server!"})}})};checkPassword();const toggelNewPasswordVisibilty=()=>{const passwordVisibilityBtn=document.querySelector("#newPasswordVisibilityBtn");passwordVisibilityBtn.addEventListener("click",()=>{const password=document.querySelector("#newPassword");const openEyeIcon=document.querySelector("#newPasswordOpenEye");const closeEyeIcon=document.querySelector("#newPasswordCloseEye");if(password.type==="password"){openEyeIcon.classList.replace("d-block","d-none");closeEyeIcon.classList.replace("d-none","d-block");closeEyeIcon.classList.add("selected");password.type="text"}else{closeEyeIcon.classList.replace("d-block","d-none");closeEyeIcon.classList.remove("selected");openEyeIcon.classList.replace("d-none","d-block");password.type="password"}})};const toggelConfrimPasswordVisibilty=()=>{const passwordVisibilityBtn=document.querySelector("#confirmPasswordVisibilityBtn");passwordVisibilityBtn.addEventListener("click",()=>{const password=document.querySelector("#confirmPassword");const openEyeIcon=document.querySelector("#confirmPasswordOpenEye");const closeEyeIcon=document.querySelector("#confirmPasswordCloseEye");if(password.type==="password"){openEyeIcon.classList.replace("d-block","d-none");closeEyeIcon.classList.replace("d-none","d-block");closeEyeIcon.classList.add("selected");password.type="text"}else{closeEyeIcon.classList.replace("d-block","d-none");closeEyeIcon.classList.remove("selected");openEyeIcon.classList.replace("d-none","d-block");password.type="password"}})};toggelConfrimPasswordVisibilty();toggelNewPasswordVisibilty();